# =============================================================================
# Chapter 10 values: Nonparametric Tests
#
# Run from the project root:
#   Rscript r_code/figures/chapter_10_values.R
#
# The figures are generated by r_code/figures/chapter_10.R. This script
# records the test values behind Sections 10.5 through 10.14. The five
# datasets are textbook_prices.csv, college_teacher_salary_2023.csv,
# student_lifestyle_sleep.csv, cc_risk.csv, and college_backpacks.csv.
# figures/chapter_10/values.yml is generated by save_book_values(); do not edit
# it by hand.
# =============================================================================

source("r_code/figures/_book_figs.R")

suppressPackageStartupMessages({
  library(dplyr)
  library(readr)
})

# ---- Data -------------------------------------------------------------------

textbooks <- read_csv("data/textbook_prices.csv", show_col_types = FALSE)
salary <- read_csv(
  "data/college_teacher_salary_2023.csv", show_col_types = FALSE
)
lifestyle <- read_csv(
  "data/student_lifestyle_sleep.csv", show_col_types = FALSE
)
cc_risk <- read_csv("data/cc_risk.csv", show_col_types = FALSE)
backpacks <- read_csv("data/college_backpacks.csv", show_col_types = FALSE)

textbooks <- textbooks %>%
  rename(Bookstore = 2)

# ---- Helpers ----------------------------------------------------------------

# Fisher z interval for a rank correlation, the interval reported by the
# chapter's software output.
spearman_ci <- function(rho, n, level = 0.95) {
  z <- atanh(rho)
  se <- 1 / sqrt(n - 3)
  zq <- qnorm(1 - (1 - level) / 2)
  c(tanh(z - zq * se), tanh(z + zq * se))
}

# ---- Wilcoxon signed-rank: textbook prices ---------------------------------

tb_diff <- textbooks$Bookstore - textbooks$Amazon

tb_exact <- wilcox.test(
  textbooks$Bookstore, textbooks$Amazon,
  paired = TRUE, conf.int = TRUE, exact = TRUE
)
tb_normal <- wilcox.test(
  textbooks$Bookstore, textbooks$Amazon,
  paired = TRUE, conf.int = TRUE, exact = FALSE, correct = FALSE
)
tb_normal_corrected <- wilcox.test(
  textbooks$Bookstore, textbooks$Amazon,
  paired = TRUE, conf.int = TRUE, exact = FALSE, correct = TRUE
)

# Wilcoxon null distribution: the sum of a random subset of the ranks 1 to n.
# The achieved confidence of an interval [W_(k+1), W_(N-k)] is 1 - 2 P(V <= k).
tb_walsh <- sort(outer(
  tb_diff, tb_diff, function(a, b) (a + b) / 2
)[upper.tri(diag(length(tb_diff)), diag = TRUE)])
tb_lower_rank <- which(abs(tb_walsh - 17) < 1e-9)
tb_achieved <- 1 - 2 * psignrank(tb_lower_rank - 1, length(tb_diff))

# ---- Mann-Whitney: salary by sex -------------------------------------------

salary_female <- salary$Salary[salary$Sex == 0]
salary_male <- salary$Salary[salary$Sex == 1]

mw <- wilcox.test(
  Salary ~ Sex, data = salary,
  correct = FALSE, exact = FALSE, conf.int = TRUE
)
mw_u <- unname(mw$statistic)
# Minitab reports W as the rank sum of the first group, which is U plus
# n1(n1 + 1)/2.
mw_rank_sum_female <- mw_u + length(salary_female) *
  (length(salary_female) + 1) / 2

# ---- Kruskal-Wallis: GPA by alcohol use ------------------------------------

lifestyle <- lifestyle %>%
  mutate(
    AlcoholRank = as.integer(factor(
      AlcoholUse, levels = c("Abstain", "Light", "Moderate", "Heavy")
    ))
  )

kw <- kruskal.test(GPA ~ AlcoholUse, data = lifestyle)
kw_means <- tapply(rank(lifestyle$GPA), lifestyle$AlcoholUse, mean)
kw_medians <- tapply(lifestyle$GPA, lifestyle$AlcoholUse, median)
kw_counts <- table(lifestyle$AlcoholUse)

# The unadjusted H uses the average ranks without the tie correction.
kw_n <- nrow(lifestyle)
kw_unadjusted <- 12 / (kw_n * (kw_n + 1)) *
  sum(kw_counts * (kw_means - (kw_n + 1) / 2)^2)

# ---- Spearman: age and drinking days ---------------------------------------

sp_age <- cor.test(
  cc_risk$Age, cc_risk$DaysDrink, method = "spearman", exact = FALSE
)
sp_age_ci <- spearman_ci(unname(sp_age$estimate), nrow(cc_risk))

# ---- Spearman: alcohol rank and GPA ----------------------------------------

sp_alcohol <- cor.test(
  lifestyle$GPA, lifestyle$AlcoholRank, method = "spearman", exact = FALSE
)
sp_alcohol_ci <- spearman_ci(
  unname(sp_alcohol$estimate), nrow(lifestyle)
)

# ---- Fisher exact: back problems by enrollment status ----------------------

bp_table <- table(backpacks$Status, backpacks$BackProblems)
fisher_bp <- fisher.test(bp_table)

bp_undergrad <- bp_table["U", "1"] / sum(bp_table["U", ])
bp_grad <- bp_table["G", "1"] / sum(bp_table["G", ])

# ---- Values registry --------------------------------------------------------

values <- list(
  data = list(
    textbook_rows = nrow(textbooks),
    salary_rows = nrow(salary),
    lifestyle_rows = nrow(lifestyle),
    cc_risk_rows = nrow(cc_risk),
    backpack_rows = nrow(backpacks)
  ),
  wilcoxon_textbook_prices = list(
    test = "wilcox.test(Bookstore, Amazon, paired = TRUE)",
    differences = "Bookstore - Amazon",
    n = nrow(textbooks),
    amazon_median = median(textbooks$Amazon),
    bookstore_median = median(textbooks$Bookstore),
    sample_median_difference = median(tb_diff),
    pseudo_median = unname(tb_exact$estimate),
    statistic_v = unname(tb_exact$statistic),
    exact_p = tb_exact$p.value,
    exact_ci = unname(tb_exact$conf.int),
    normal_p_no_correction = tb_normal$p.value,
    normal_ci_no_correction = unname(tb_normal$conf.int),
    normal_p_with_correction = tb_normal_corrected$p.value,
    achieved_confidence = tb_achieved,
    note = paste(
      "The chapter reports the sample medians (bookstore 126.00, Amazon",
      "95.50) and the sample median difference (36.00). The 34.5 value in",
      "the original output was Minitab's Hodges-Lehmann estimate; the",
      "chapter does not use it. The test values match R's normal",
      "approximation without a continuity correction: p = 0.00192 and CI",
      "[17.0, 58.0]. The achieved confidence is the exact coverage of that",
      "interval (0.9493). R's exact test gives p = 0.00076 and CI [15.0,",
      "58.5]."
    )
  ),
  mann_whitney_salary = list(
    test = "wilcox.test(Salary ~ Sex, correct = FALSE, exact = FALSE)",
    n_female = length(salary_female),
    n_male = length(salary_male),
    median_female = median(salary_female),
    median_male = median(salary_male),
    u_statistic = mw_u,
    rank_sum_female = mw_rank_sum_female,
    p = mw$p.value,
    difference_in_location = unname(mw$estimate),
    ci = unname(mw$conf.int),
    note = paste(
      "Sex is 0 = female and 1 = male; Salary is in thousands of dollars.",
      "R reports U = 4040.5, which is the statistic now printed in the",
      "chapter. Minitab's W = 8793.5 is the rank sum for the female group,",
      "which equals U + 97*98/2. The p-value and CI agree."
    )
  ),
  kruskal_wallis_gpa = list(
    test = "kruskal.test(GPA ~ AlcoholUse)",
    n = kw_n,
    group_counts = as.list(kw_counts),
    group_medians = as.list(kw_medians),
    group_mean_ranks = as.list(kw_means),
    h_adjusted_for_ties = unname(kw$statistic),
    h_unadjusted_for_ties = kw_unadjusted,
    df = unname(kw$parameter),
    p = kw$p.value,
    note = paste(
      "R's kruskal.test always applies the tie correction. The unadjusted",
      "statistic is 5.44 and the adjusted statistic is 5.46, matching the",
      "two rows in the chapter's output."
    )
  ),
  spearman_age_daysdrink = list(
    test = "cor.test(Age, DaysDrink, method = 'spearman', exact = FALSE)",
    n = nrow(cc_risk),
    rho = unname(sp_age$estimate),
    p = sp_age$p.value,
    ci_fisher_z = sp_age_ci,
    note = "The confidence interval is a Fisher z interval for rho."
  ),
  spearman_alcohol_gpa = list(
    test = paste(
      "cor.test(GPA, AlcoholRank, method = 'spearman', exact = FALSE);",
      "AlcoholRank = 1 Abstain, 2 Light, 3 Moderate, 4 Heavy"
    ),
    n = nrow(lifestyle),
    rho = unname(sp_alcohol$estimate),
    p = sp_alcohol$p.value,
    ci_fisher_z = sp_alcohol_ci,
    note = paste(
      "The computed interval is (-0.263, -0.021), matching the chapter."
    )
  ),
  fisher_back_problems = list(
    test = "fisher.test(table(Status, BackProblems))",
    table = as.data.frame(bp_table, responseName = "count"),
    p = fisher_bp$p.value,
    grad_share_with_problems = bp_grad,
    undergrad_share_with_problems = bp_undergrad,
    note = "Rows are Status (G = graduate, U = undergraduate); columns are BackProblems (0/1)."
  ),
  table_10_1 = list(
    note = "Notation table; no calculated values."
  ),
  figures = list(
    figure_10_1 = list(
      note = paste(
        "Boxplot of the 16 paired textbook price differences; median 36.00;",
        "one book is 123 dollars more at the bookstore."
      )
    ),
    figure_10_2 = list(
      note = "Histograms of salary by sex; medians 60 and 75 (thousands of dollars)."
    ),
    figure_10_3 = list(
      note = "Boxplots of GPA by AlcoholUse; medians 3.40, 3.30, 3.25, 3.10."
    ),
    figure_10_4 = list(
      note = paste(
        "Histogram of DaysDrink: 123 zeros (28%), median 3 days, mean 6.5",
        "days. Zero is the modal category."
      )
    ),
    figure_10_5 = list(
      note = paste(
        "Grouped bar of BackProblems by Status; 3 graduate students (0 with",
        "problems) and 97 undergraduates (32 with problems)."
      )
    )
  )
)

save_book_values(
  chapter = 10,
  values = values,
  conventions = list(
