# ---- Console summary --------------------------------------------------------

cat("\n--- Chapter 10 summary ---\n")
cat("Textbook medians: Amazon", median(textbooks$Amazon),
    " Bookstore", median(textbooks$Bookstore),
    " median diff", median(tb_diff),
    " pseudo-median", unname(tb_exact$estimate), "\n")
cat("Textbook exact p:", tb_exact$p.value,
    " normal p:", tb_normal$p.value,
    " exact CI:", unname(tb_exact$conf.int),
    " normal CI:", unname(tb_normal$conf.int), "\n")
cat("Salary medians:", median(salary_female), median(salary_male),
    " U:", mw_u, " W(rank sum):", mw_rank_sum_female,
    " p:", mw$p.value, " CI:", unname(mw$conf.int), "\n")
cat("Kruskal H:", unname(kw$statistic),
    " unadjusted:", kw_unadjusted,
    " p:", kw$p.value, "\n")
cat("Spearman age/drinks rho:", unname(sp_age$estimate),
    " p:", sp_age$p.value, " CI:", sp_age_ci, "\n")
